import{_ as a,o as t,c as s,ag as i}from"./chunks/framework.CrXGS008.js";const g=JSON.parse('{"title":"Repair Station","description":"","frontmatter":{},"headers":[],"relativePath":"fr/repair-station/index.md","filePath":"fr/repair-station/index.md"}'),n={name:"fr/repair-station/index.md"};function r(o,e,l,p,u,c){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="repair-station" tabindex="-1">Repair Station <a class="header-anchor" href="#repair-station" aria-label="Permalink to &quot;Repair Station&quot;">​</a></h1><p>On roule sur une station de réparation, on choisit une prestation, et le véhicule est réparé sur place : moteur, carrosserie et pneus, avec le son et les étincelles. Le prix suit les dégâts : une voiture éraflée paie moins qu&#39;une épave. Les stations se placent en jeu et chaque réglage se modifie en jeu.</p><h2 id="fonctionnalites" tabindex="-1">Fonctionnalités <a class="header-anchor" href="#fonctionnalites" aria-label="Permalink to &quot;Fonctionnalités&quot;">​</a></h2><ul><li><strong>Trois prestations d&#39;office</strong> : dépannage rapide (moteur), carrosserie (carrosserie et pneus), réparation complète. Le nom, le prix, la durée et les parties réparées se changent. Voir <a href="/fr/repair-station/settings">Réglages</a>.</li><li><strong>Prix selon les dégâts</strong> : le prix suit les dégâts des parties réparées, jusqu&#39;à un pourcentage minimum. Les véhicules intacts sont refusés.</li><li><strong>Éditeur de stations en jeu</strong> : créez une station là où vous êtes, déplacez la zone d&#39;arrêt et un prop facultatif au clavier, enregistrez. Voir <a href="/fr/repair-station/stations">Stations</a>.</li><li><strong>Les mécaniciens d&#39;abord</strong> : les stations ferment tant qu&#39;assez de mécaniciens sont en service, les joueurs font appel à eux.</li><li><strong>Juste et sûr</strong> : un véhicule par station, contrôles du conducteur et de la vitesse, paiements validés par le serveur. Une réparation annulée est remboursée sur le compte débité.</li><li><strong>Remises par métier</strong>, pourcentage de prix par station, et paiement en liquide, par la banque, ou en liquide puis par la banque.</li><li><strong>Tout dans <code>/nay</code></strong> : prestations, prix, stations, métiers de mécanicien, blips avec un choix visuel d&#39;icône et de couleur.</li><li><strong>API HTTP et webhooks</strong> : historique des réparations, statistiques et stations pour votre site ou votre bot, un message Discord à chaque réparation. Voir <a href="/fr/repair-station/api">API et webhooks</a>.</li><li><strong>Extensible</strong> : une seconde ressource peut changer les prix, fermer des stations et participer à chaque réparation. Voir <a href="/fr/repair-station/api#extensions">Extensions</a>.</li><li><strong>Six langues</strong> : anglais, français, espagnol, portugais, polonais, allemand.</li></ul><h2 id="compatibilite" tabindex="-1">Compatibilité <a class="header-anchor" href="#compatibilite" aria-label="Permalink to &quot;Compatibilité&quot;">​</a></h2><ul><li>Frameworks : ESX Legacy, QBCore, QBox, ox_core, détectés automatiquement.</li><li>Dépendances : oxmysql et <code>nay_lib</code> (fourni avec votre achat).</li></ul><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ensure oxmysql</span></span>
<span class="line"><span>ensure nay_lib</span></span>
<span class="line"><span>ensure nay_repair</span></span></code></pre></div><p>Les étapes complètes sont sur la page <a href="/fr/getting-started">Prise en main</a>. Donnez-vous ensuite <code>nay_repair.config</code> (ou <code>nay.admin</code>) et ouvrez <code>/nay</code>. Trois stations sont prêtes d&#39;office : Hayes Autos, Sandy Shores et Paleto Bay.</p>`,9)])])}const m=a(n,[["render",r]]);export{g as __pageData,m as default};
